          arr.items.push(parseValue([...path.slice(0, -1), `${path[path.length - 1]}[${arr.items.length}]`]))
          ws()
          if (s[p] === ',') {
            p++
            continue
          }
          if (s[p] === ']') {
            p++
            return arr
          }
          if (atEnd()) fail('unterminated array')
          fail('trailing text after a value')
