      const st = p
      while (p < s.length && !isWs(s[p]) && !',]};'.includes(s[p])) p++
      const w = s.slice(st, p)
      if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
      if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
      if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
      return fail(`invalid value ${w}`)
    }

    ws()
    if (atEnd()) continue
    if (s[p] === '[') {
      const dbl = s[p + 1] === '['
      p += dbl ? 2 : 1
      const names = parseDotted()
      ws()
      const close = dbl ? ']]' : ']'
      if (s.slice(p, p + close.length) !== close) fail('unterminated table header')
      p += close.length
      ws()
      if (!atEnd()) fail('trailing text after a table header')
      const [parent, ppath] = walk(root, [], names.slice(0, -1))
      const k = names[names.length - 1]
      const path = [...ppath, k]
      const ex = parent.map.get(k)
      if (dbl) {
        if (!ex) {
          const arr = { t: 'array', items: [], aot: true }
          parent.map.set(k, arr)
          current = table()
          current.header = true
          arr.items.push(current)
        } else if (ex.t !== 'array' || !ex.aot) fail(`${path.join('.')} is not an array of tables`)
        else {
          current = table()
          current.header = true
          ex.items.push(current)
        }
      } else if (!ex) {
        current = table()
        current.header = true
        parent.map.set(k, current)
      } else if (ex.t !== 'table') fail(`${path.join('.')} is not a table`)
      else if (ex.header) fail(`table ${path.join('.')} is defined twice`)
      else {
        ex.header = true
        current = ex
      }
      curPath = path
      continue
    }
    const names = parseDotted()
    if (s[p] !== '=') fail('expected key = value')
    p++
    const v = parseValue([...curPath, ...names])
    ws()
    if (!atEnd()) fail('trailing text after a value')
    assign(current, curPath, names, v)
  }
  return root
}
